// Reorder report: packs needed to lift each short item back to its threshold.

@pure
fn packsFor(shortfall: Int, pack: Int) -> Int {
    if shortfall <= 0 || pack <= 0 {
        ret 0;
    }
    ret (shortfall + pack - 1) div pack;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("TOON unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("stock_levels.json");
    }
    let root: ToonNode = toon_root(doc);
    let site: Text = toon_get_text_or(root, "warehouse", "?");
    let items: ToonNode = toon_key(root, "items");

    let okCount: Int = 0;
    let orderLines: Int = 0;
    let units: Int = 0;

    fx { println("warehouse ", site); }

    loop item in items {
        let sku: Text = toon_get_text_or(item, "sku", "?");
        let onHand: Int = toon_get_int_or(item, "on_hand", 0);
        let level: Int = toon_get_int_or(item, "reorder_at", 0);
        let pack: Int = toon_get_int_or(item, "pack", 1);
        if onHand >= level {
            okCount = okCount + 1;
            continue;
        }
        let packs: Int = packsFor(level - onHand, pack);
        let qty: Int = packs * pack;
        orderLines = orderLines + 1;
        units = units + qty;
        let note: Text = "";
        if onHand == 0 {
            note = " (out of stock)";
        }
        fx { println("ORDER ", sku, " ", packs, " x ", pack, " = ", qty, note); }
    }

    fx {
        println("ok: ", okCount);
        println("to order: ", orderLines);
        println("units: ", units);
    }
    toon_close(doc);
    ret;
}

// Effective service settings: dotted paths with defaults, counting defaults used.

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"service\":{\"name\":\"ledger\",\"http\":{\"port\":8443,\"tls\":true},\"workers\":6},\"limits\":{\"rps\":250},\"log\":{\"format\":\"json\"}}");
    let cfg: ToonNode = toon_root(doc);
    let defaulted: Int = 0;

    let name: Text = toon_get_text_or(cfg, "service.name", "unnamed");
    if !toon_has_key(cfg, "service.name") { defaulted = defaulted + 1; }
    let port: Int = toon_get_int_or(cfg, "service.http.port", 80);
    if !toon_has_key(cfg, "service.http.port") { defaulted = defaulted + 1; }
    let tls: Bool = toon_get_bool_or(cfg, "service.http.tls", false);
    if !toon_has_key(cfg, "service.http.tls") { defaulted = defaulted + 1; }
    let workers: Int = toon_get_int_or(cfg, "service.workers", 1);
    if !toon_has_key(cfg, "service.workers") { defaulted = defaulted + 1; }
    let timeoutMs: Int = toon_get_int_or(cfg, "service.http.timeout_ms", 30000);
    if !toon_has_key(cfg, "service.http.timeout_ms") { defaulted = defaulted + 1; }
    let rps: Int = toon_get_int_or(cfg, "limits.rps", 100);
    if !toon_has_key(cfg, "limits.rps") { defaulted = defaulted + 1; }
    let burst: Int = toon_get_int_or(cfg, "limits.burst", rps * 2);
    if !toon_has_key(cfg, "limits.burst") { defaulted = defaulted + 1; }
    let level: Text = toon_get_text_or(cfg, "log.level", "info");
    if !toon_has_key(cfg, "log.level") { defaulted = defaulted + 1; }
    let format: Text = toon_get_text_or(cfg, "log.format", "text");
    if !toon_has_key(cfg, "log.format") { defaulted = defaulted + 1; }
    let admin: Bool = toon_get_bool_or(cfg, "service.admin.enabled", false);
    if !toon_has_key(cfg, "service.admin.enabled") { defaulted = defaulted + 1; }

    let scheme: Text = if tls { "https" } else { "http" };

    fx {
        println("name = ", name);
        println("port = ", port);
        println("tls = ", tls);
        println("workers = ", workers);
        println("timeout_ms = ", timeoutMs);
        println("rps = ", rps);
        println("burst = ", burst);
        println("log.level = ", level);
        println("log.format = ", format);
        println("admin = ", admin);
        println("defaults used = ", defaulted);
        println("url = ", scheme, "://", name, ":", port);
    }
    toon_close(doc);
    ret;
}

// Classify every cell of a mixed-type JSON row and summarise it.

fn main() -> Void {
    let doc: ToonDoc = toon_parse("[42, \"n/a\", 3.5, true, null, -7, \"12\", 0.25, false, {\"ref\": \"B2\"}, [1, 2, 3], \"\"]");
    let row: ToonNode = toon_root(doc);

    let numericSum: Real = 0.0;
    let texts: Int = 0;
    let trueFlags: Int = 0;
    let blank: Int = 0;

    loop i in 0..toon_len(row) {
        let cell: ToonNode = toon_at(row, i);
        if toon_is_int(cell) {
            let v: Int = toon_int_value(cell);
            numericSum = numericSum + v;
            fx { println("cell ", i, ": int ", v); }
        } else if toon_is_real(cell) {
            let r: Real = toon_real_value(cell);
            numericSum = numericSum + r;
            fx { println("cell ", i, ": real ", r:0:2); }
        } else if toon_is_text(cell) {
            let s: Text = toon_text_value(cell);
            texts = texts + 1;
            if string_len(s) == 0 { blank = blank + 1; }
            fx { println("cell ", i, ": text \"", s, "\""); }
        } else if toon_is_bool(cell) {
            let b: Bool = toon_bool_value(cell);
            if b { trueFlags = trueFlags + 1; }
            fx { println("cell ", i, ": bool ", b); }
        } else if toon_is_null(cell) {
            blank = blank + 1;
            fx { println("cell ", i, ": empty"); }
        } else if toon_is_arr(cell) {
            fx { println("cell ", i, ": array of ", toon_len(cell)); }
        } else {
            fx { println("cell ", i, ": object"); }
        }
        toon_free(cell);
    }

    fx {
        println("numeric sum = ", numericSum:0:2);
        println("texts = ", texts);
        println("true flags = ", trueFlags);
        println("blank = ", blank);
    }
    toon_close(doc);
    ret;
}

// Group a root array of orders by region (first-appearance order) with
// paid/refunded sums, the best net region, and the pending order ids.

type Bucket {
    region: Text = "";
    n: Int = 0;
    paid: Int = 0;
    refunded: Int = 0;
}

fn findBucket(buckets: Bucket[], region: Text) -> Int {
    loop k in 0..length(buckets) {
        if buckets[k].region == region {
            ret k;
        }
    }
    ret -1;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("cannot parse orders"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("orders.json");
    }
    let orders: ToonNode = toon_root(doc);

    let buckets: Bucket[] = [];
    let pending: Text = "";

    loop order in orders {
        let region: Text = toon_get_text_or(order, "region", "unknown");
        let status: Text = toon_get_text_or(order, "status", "");
        let total: Int = toon_get_int_or(order, "total", 0);
        let at: Int = findBucket(buckets, region);
        if at < 0 {
            buckets = buckets + [new Bucket { region: region }];
            at = length(buckets) - 1;
        }
        let b: Bucket = buckets[at];
        b.n = b.n + 1;
        if status == "paid" {
            b.paid = b.paid + total;
        } else if status == "refunded" {
            b.refunded = b.refunded + total;
        } else if status == "pending" {
            let id: Text = toon_get_text_or(order, "id", "?");
            if pending != "" { pending = pending + ","; }
            pending = pending + id;
        }
    }

    let bestName: Text = "";
    let bestNet: Int = 0;
    let grand: Int = 0;
    loop k in 0..length(buckets) {
        let b: Bucket = buckets[k];
        let net: Int = b.paid - b.refunded;
        grand = grand + net;
        if k == 0 || net > bestNet {
            bestNet = net;
            bestName = b.region;
        }
        fx { println(b.region, ": n=", b.n, ", paid ", b.paid, ", refunded ", b.refunded, ", net ", net); }
    }
    if pending == "" { pending = "none"; }

    fx {
        println("best region = ", bestName, " (", bestNet, ")");
        println("pending = ", pending);
        println("grand net = ", grand);
    }
    toon_close(doc);
    ret;
}

// Rank students by mean score (stable on ties), list those without scores,
// and report the class-wide mean and the best single score.

type Entry {
    name: Text = "";
    sum: Int = 0;
    count: Int = 0;
}

@pure
fn above(a: Entry, b: Entry) -> Bool {
    // a strictly ahead of b: compare sum/count by cross-multiplying
    ret a.sum * b.count > b.sum * a.count;
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"course\":\"chem-2\",\"students\":[{\"name\":\"Ines\",\"scores\":[78,85,90]},{\"name\":\"Bo\",\"scores\":[92,88]},{\"name\":\"Cato\",\"scores\":[]},{\"name\":\"Dara\",\"scores\":[85,90,78]},{\"name\":\"Eli\"},{\"name\":\"Fay\",\"scores\":[100,61,70,95]}]}");
    let root: ToonNode = toon_root(doc);
    let course: Text = toon_get_text_or(root, "course", "");
    let students: ToonNode = toon_key(root, "students");

    let ranked: Entry[] = [];
    let missing: Text = "";
    let allSum: Int = 0;
    let allCount: Int = 0;
    let bestScore: Int = -1;
    let bestName: Text = "";

    loop s in 0..toon_len(students) {
        let st: ToonNode = toon_at(students, s);
        let name: Text = toon_get_text_or(st, "name", "?");
        let scores: ToonNode = toon_key_or(st, "scores", toon_null());
        let n: Int = toon_len(scores);
        if n == 0 {
            if missing != "" { missing = missing + ", "; }
            missing = missing + name;
            continue;
        }
        let e: Entry = new Entry { name: name, count: n };
        loop j in 0..n {
            let v: Int = toon_int_value(toon_at(scores, j));
            e.sum = e.sum + v;
            if v > bestScore {
                bestScore = v;
                bestName = name;
            }
        }
        allSum = allSum + e.sum;
        allCount = allCount + n;
        // stable insertion: move past every entry that is not strictly below e
        let at: Int = length(ranked);
        loop k in 0..length(ranked) {
            if above(e, ranked[k]) {
                at = k;
                break;
            }
        }
        ranked = ranked[0..at] + [e] + ranked[at..length(ranked)];
    }

    let classAvg: Real = 0.0;
    if allCount > 0 { classAvg = allSum * 1.0 / allCount; }

    fx {
        println("course ", course);
        loop k in 0..length(ranked) {
            let avg: Real = ranked[k].sum * 1.0 / ranked[k].count;
            println("#", k + 1, " ", ranked[k].name, " ", avg:0:2, " (", ranked[k].count, " scores)");
        }
        println("no scores: ", missing);
        println("class average = ", classAvg:0:2);
        println("best single score = ", bestScore, " (", bestName, ")");
    }
    toon_close(doc);
    ret;
}

// Contact audit: tell "no contact object" apart from "contact without email"
// and from "email present but blank"; build the active mailing list.

fn main() -> Void {
    if !has_toon() {
        fx { println("member audit skipped: no TOON support"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("members.json");
    }
    let root: ToonNode = toon_root(doc);
    let members: ToonNode = toon_key(root, "members");

    let byEmail: Int = 0;
    let byPhone: Int = 0;
    let unreachable: Int = 0;
    let mailing: Text = "";

    loop i in 0..toon_len(members) {
        let m: ToonNode = toon_at(members, i);
        let id: Int = toon_get_int_or(m, "id", 0);
        let name: Text = toon_get_text_or(m, "name", "(no name)");
        let active: Bool = toon_get_bool_or(m, "active", true);

        let status: Text = "no contact";
        let email: Text = "";
        let phone: Text = "";
        if toon_has_key(m, "contact") {
            let contact: ToonNode = toon_key(m, "contact");
            phone = toon_get_text_or(contact, "phone", "");
            if !toon_has_key(contact, "email") {
                status = "no email";
            } else {
                email = toon_get_text_or(contact, "email", "");
                status = if email == "" { "email blank" } else { "email " + email };
            }
        }

        if email != "" { byEmail = byEmail + 1; }
        if phone != "" { byPhone = byPhone + 1; }
        if email == "" && phone == "" { unreachable = unreachable + 1; }
        if active && email != "" {
            if mailing != "" { mailing = mailing + ";"; }
            mailing = mailing + email;
        }

        let suffix: Text = if active { "" } else { " [inactive]" };
        fx { println("#", id, " ", name, ": ", status, suffix); }
    }

    fx {
        println("reachable by email = ", byEmail);
        println("reachable by phone = ", byPhone);
        println("unreachable = ", unreachable);
        println("mailing list = ", mailing);
    }
    toon_close(doc);
    ret;
}

// Validate a meter series: whole-number readings count, fractional readings
// and junk values are rejected separately; then mean, extremes, range.

@pure
fn appendIndex(list: Text, i: Int) -> Text {
    if list == "" {
        ret int_to_text(i);
    }
    ret list + "," + int_to_text(i);
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"meter\":\"pump-7\",\"unit\":\"pulses\",\"samples\":[120, 135, null, 98, \"ERR\", 142, 101.5, true, 111]}");
    let root: ToonNode = toon_root(doc);
    let samples: ToonNode = toon_key(root, "samples");

    let readings: Int[] = [];
    let positions: Int[] = [];
    let fracAt: Text = "";
    let junkAt: Text = "";
    let fracCount: Int = 0;
    let junkCount: Int = 0;

    loop i in 0..toon_len(samples) {
        let cell: ToonNode = toon_at(samples, i);
        if toon_is_int(cell) {
            readings = readings + [toon_int_value(cell)];
            positions = positions + [i];
        } else if toon_is_real(cell) {
            fracCount = fracCount + 1;
            fracAt = appendIndex(fracAt, i);
        } else {
            junkCount = junkCount + 1;
            junkAt = appendIndex(junkAt, i);
        }
    }

    let n: Int = length(readings);
    let sum: Int = 0;
    let lo: Int = readings[0];
    let hi: Int = readings[0];
    let loAt: Int = positions[0];
    let hiAt: Int = positions[0];
    loop k in 0..n {
        sum = sum + readings[k];
        if readings[k] < lo { lo = readings[k]; loAt = positions[k]; }
        if readings[k] > hi { hi = readings[k]; hiAt = positions[k]; }
    }
    let mean: Real = sum * 1.0 / n;
    let above: Int = 0;
    loop r in readings {
        if r > mean { above = above + 1; }
    }

    let label: Text = toon_get_text_or(root, "meter", "?");
    let unit: Text = toon_get_text_or(root, "unit", "?");
    fx {
        println("meter ", label, " (", unit, ")");
        println("valid = ", n);
        println("fractional = ", fracCount, " at ", fracAt);
        println("junk = ", junkCount, " at ", junkAt);
        println("mean = ", mean:0:2);
        println("min = ", lo, " at ", loAt);
        println("max = ", hi, " at ", hiAt);
        println("range = ", hi - lo);
        println("above mean = ", above);
    }
    toon_close(doc);
    ret;
}

// Inventory a cluster whose node specs are only partly filled in: walk
// cluster -> nodes -> spec -> mem with null-absorbing lookups.

fn main() -> Void {
    if !has_toon() {
        fx { println("no structured data support"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("cluster.json");
    }
    let cluster: ToonNode = toon_key(toon_root(doc), "cluster");
    let nodes: ToonNode = toon_key_or(cluster, "nodes", toon_null());

    let cpuTotal: Int = 0;
    let memTotal: Int = 0;
    let incomplete: Int = 0;
    let gpuHosts: Text = "";
    let bigHost: Text = "";
    let bigMem: Int = -1;

    loop i in 0..toon_len(nodes) {
        let node: ToonNode = toon_at(nodes, i);
        let host: Text = toon_get_text_or(node, "host", "?");
        let spec: ToonNode = toon_key_or(node, "spec", toon_null());
        let mem: ToonNode = toon_key_or(spec, "mem", toon_null());
        let cpu: Int = toon_get_int_or(spec, "cpu", -1);
        let gb: Int = toon_get_int_or(mem, "gb", -1);
        let tags: ToonNode = toon_key_or(node, "tags", toon_null());

        let tagText: Text = "";
        loop t in 0..toon_len(tags) {
            let tag: Text = toon_text_value(toon_at(tags, t));
            if t > 0 { tagText = tagText + "|"; }
            tagText = tagText + tag;
            if tag == "gpu" {
                if gpuHosts != "" { gpuHosts = gpuHosts + ","; }
                gpuHosts = gpuHosts + host;
            }
        }
        if tagText == "" { tagText = "-"; }

        let cpuText: Text = "?";
        let memText: Text = "?";
        if cpu >= 0 {
            cpuText = int_to_text(cpu);
            cpuTotal = cpuTotal + cpu;
        }
        if gb >= 0 {
            memText = int_to_text(gb) + "G";
            memTotal = memTotal + gb;
            if gb > bigMem { bigMem = gb; bigHost = host; }
        }
        if cpu < 0 || gb < 0 { incomplete = incomplete + 1; }

        fx { println(host, ": cpu ", cpuText, ", mem ", memText, ", tags ", tagText); }
    }

    fx {
        println("cluster ", toon_get_text_or(cluster, "name", "?"), ": ", toon_len(nodes), " nodes, ", cpuTotal, " cpu, ", memTotal, "G");
        println("gpu nodes = ", gpuHosts);
        println("incomplete = ", incomplete);
        println("largest memory = ", bigHost);
    }
    toon_close(doc);
    ret;
}

// Monthly spend: group a root array of dated expenses by YYYY-MM (first
// appearance order), the food share of the grand total, the largest expense.

fn main() -> Void {
    if !has_toon() {
        fx { println("spend report unavailable"); }
        ret;
    }

    let doc: ToonDoc = toon_parse("[{\"date\":\"2026-01-04\",\"cat\":\"food\",\"amt\":12.40},{\"date\":\"2026-01-19\",\"cat\":\"travel\",\"amt\":88.00},{\"date\":\"2026-02-02\",\"cat\":\"food\",\"amt\":9.95},{\"date\":\"2026-01-27\",\"cat\":\"food\",\"amt\":15.10},{\"date\":\"2026-03-11\",\"cat\":\"rent\",\"amt\":700.00},{\"date\":\"2026-02-14\",\"cat\":\"gift\",\"amt\":45.50},{\"date\":\"2026-03-30\",\"cat\":\"food\",\"amt\":21.05}]");
    let expenses: ToonNode = toon_root(doc);

    let months: Text[] = [];
    let counts: Int[] = [];
    let sums: Real[] = [];
    let food: Real = 0.0;
    let grand: Real = 0.0;
    let topAmt: Real = -1.0;
    let topDate: Text = "";
    let topCat: Text = "";

    loop e in expenses {
        let date: Text = toon_get_text_or(e, "date", "0000-00-00");
        let cat: Text = toon_get_text_or(e, "cat", "");
        let amt: Real = toon_get_real_or(e, "amt", 0.0);
        let month: Text = copy(date, 0, 7);

        let slot: Int = -1;
        loop k in 0..length(months) {
            if months[k] == month { slot = k; break; }
        }
        if slot < 0 {
            months = months + [month];
            counts = counts + [0];
            sums = sums + [0.0];
            slot = length(months) - 1;
        }
        counts[slot] = counts[slot] + 1;
        sums[slot] = sums[slot] + amt;

        grand = grand + amt;
        if cat == "food" { food = food + amt; }
        if amt > topAmt { topAmt = amt; topDate = date; topCat = cat; }
    }

    fx {
        loop k in 0..length(months) {
            println(months[k], ": ", counts[k], " entries, ", sums[k]:0:2);
        }
        println("food share = ", food:0:2, " of ", grand:0:2);
        println("largest = ", topDate, " ", topCat, " ", topAmt:0:2);
    }
    toon_close(doc);
    ret;
}

// Percent-encode a query string into a memory stream, one byte per append:
// unreserved bytes and the = and & separators pass through, every other byte
// becomes '%' plus two uppercase hex digits.

@pure
fn keepsAsIs(code: Int) -> Bool {
    if code >= 48 && code <= 57 { ret true; }    // 0-9
    if code >= 65 && code <= 90 { ret true; }    // A-Z
    if code >= 97 && code <= 122 { ret true; }   // a-z
    ret code == ord("-") || code == ord("_") || code == ord(".") || code == ord("~")
        || code == ord("=") || code == ord("&");
}

@pure
fn hexDigit(v: Int) -> Int {
    if v < 10 { ret 48 + v; }
    ret 55 + v;                                  // 10 -> 'A'
}

fn main() -> Void {
    let query: Text = "q=red shoes&max=40%&path=a/b c";
    let out: MStream = mstreamcreate();
    let escaped: Int = 0;

    loop i in 0..string_len(query) {
        let code: Int = ord(query[i]);
        if keepsAsIs(code) {
            mstreamappendbyte(out, code);
        } else {
            escaped = escaped + 1;
            mstreamappendbyte(out, 37);              // '%'
            mstreamappendbyte(out, hexDigit(code >> 4));
            mstreamappendbyte(out, hexDigit(code & 15));
        }
    }

    let encoded: Text = mstreambuffer(out);
    mstreamfree(out);
    fx {
        println("input = ", query);
        println("encoded = ", encoded);
        println("escaped = ", escaped);
        println("bytes = ", string_len(encoded));
    }
    ret;
}

// Memory-stream round trip: seed a stream from text, append a line byte by
// byte, save it to disk, load it into a fresh stream and tally the lines.

fn main() -> Void {
    let draft: MStream = mstreamfromstring("alpha,3\nbeta,12\ngamma,7\n");
    let extra: Text = "delta,5\n";
    loop i in 0..string_len(extra) {
        mstreamappendbyte(draft, ord(extra[i]));
    }
    fx {
        mstreamsavetofile(draft, "snapshot.txt");
    }
    mstreamfree(draft);

    let loaded: MStream = mstreamcreate();
    fx {
        mstreamloadfromfile(loaded, "snapshot.txt");
    }
    let body: Text = mstreambuffer(loaded);
    mstreamfree(loaded);

    let lines: Text[] = split(body, "\n");
    let count: Int = 0;
    let total: Int = 0;
    loop line in lines {
        if line == "" { continue; }
        let parts: Text[] = split(line, ",");
        let value: Int = parse_int(parts[1]);
        count = count + 1;
        total = total + value;
        fx { println(parts[0], " -> ", value); }
    }
    fx {
        println("lines = ", count);
        println("total = ", total);
        println("bytes = ", string_len(body));
    }
    ret;
}

// Treat a saved API response like an HTTP body: load it into a memory
// stream, parse the stream's text as JSON, and summarise the results page.

fn main() -> Void {
    if !has_toon() {
        fx { println("json support missing"); }
        ret;
    }

    let body: MStream = mstreamcreate();
    fx {
        mstreamloadfromfile(body, "response.json");
    }
    let text: Text = mstreambuffer(body);
    mstreamfree(body);

    let doc: ToonDoc = toon_parse(text);
    let root: ToonNode = toon_root(doc);
    let status: Text = toon_get_text_or(root, "status", "missing");

    fx { println("body bytes = ", string_len(text)); }
    if status != "ok" {
        fx { println("request failed: ", status); }
        toon_close(doc);
        ret;
    }

    let results: ToonNode = toon_key(root, "results");
    let bugs: Int = 0;
    let topVotes: Int = -1;
    let topTitle: Text = "";

    fx { println("status = ok, page ", toon_get_int_or(root, "page.number", 0), " of size ", toon_get_int_or(root, "page.size", 0)); }

    loop r in results {
        let title: Text = toon_get_text_or(r, "title", "");
        let votes: Int = toon_get_int_or(r, "votes", 0);
        let labels: ToonNode = toon_key_or(r, "labels", toon_null());
        let joined: Text = "";
        let isBug: Bool = false;
        loop j in 0..toon_len(labels) {
            let lab: Text = toon_text_value(toon_at(labels, j));
            if j > 0 { joined = joined + ","; }
            joined = joined + lab;
            if lab == "bug" { isBug = true; }
        }
        if joined == "" { joined = "-"; }
        if isBug { bugs = bugs + 1; }
        if votes > topVotes { topVotes = votes; topTitle = title; }
        fx { println(toon_get_int_or(r, "id", 0), " ", title, " (", votes, ") ", joined); }
    }

    fx {
        println("bugs = ", bugs);
        println("top = ", topTitle);
    }
    toon_close(doc);
    ret;
}
